window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3f8cbaf6db33b46b"]={"versions": [{"id": "FIG-3f8cbaf6db33b46b", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der AUTOSAR-ECU-Konfigurationsparameter (BSW Module Description / EcucModuleDef) für das BSW-Modul Crypto Service Manager (CSM) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die oberste Konfigurationshierarchie und die Gliederung der Container-Struktur des Moduls <code>Csm</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist das Modul <code>Csm</code> vom Metatyp <code>EcucModuleDef</code> (Multiplizität 0..1). Über Kompositionsbeziehungen (Rolle <code>+container</code>) sind sieben Untercontainer des Metatyps <code>EcucParamConfContainerDef</code> zugeordnet:</p>\n<ul class=\"fig-list\"><li><code>CsmGeneral</code>: Allgemeine Modulkonfiguration (Multiplizität implizit 1..1, da keine Einschränkung angegeben).\n</li><li><code>CsmJobs</code>: Job-Definitionen und -Verwaltung (Multiplizität 0..1).\n</li><li><code>CsmKeys</code>: Schlüsselverwaltung und Key-Konfiguration (Multiplizität 0..1).\n</li><li><code>CsmPrimitives</code>: Kryptografische Primitiven und Algorithmen (Multiplizität 0..*).\n</li><li><code>CsmQueues</code>: Warteschlangen zur asynchronen Jobabwicklung (Multiplizität 0..1).\n</li><li><code>CsmCallbacks</code>: Callback-Konfiguration für Benachrichtigungen (Multiplizität 0..1).\n</li><li><code>CsmInOutRedirections</code>: Umleitungen von Ein- und Ausgabedaten (Multiplizität 0..1).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell- bzw. Konfigurationsstrukturdiagramm stellt die Abbildung keine Laufzeitaufrufe oder sequenziellen Nachrichtenflüsse dar. Sie bildet die statische Gliederung ab, anhand derer Konfigurationswerkzeuge (ECU Configuration Toolchain) die Parametersätze des CSM instanziieren und validieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell definiert verbindliche Vorgaben für die XML-basierte Konfigurationsbeschreibung (ARXML) des Crypto Service Managers. Generatoren und Konfigurationseditoren müssen die Multiplizitäten einhalten: <code>CsmPrimitives</code> erlaubt als einziger Untercontainer eine unbegrenzte Anzahl von Instanzen (0..*), während <code>CsmJobs</code>, <code>CsmKeys</code>, <code>CsmQueues</code>, <code>CsmCallbacks</code> und <code>CsmInOutRedirections</code> jeweils maximal einmal (0..1) konfiguriert werden dürfen. <code>CsmGeneral</code> ist für eine vollständige Modulkonfiguration obligatorisch.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-dea8b06ee6403db6", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der AUTOSAR-ECU-Konfigurationsparameter (BSW Module Description / EcucModuleDef) für das BSW-Modul Crypto Service Manager (CSM) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die oberste Konfigurationshierarchie und die Gliederung der Container-Struktur des Moduls <code>Csm</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist das Modul <code>Csm</code> vom Metatyp <code>EcucModuleDef</code> (Multiplizität 0..1). Über Kompositionsbeziehungen (Rolle <code>+container</code>) sind sieben Untercontainer des Metatyps <code>EcucParamConfContainerDef</code> zugeordnet:</p>\n<ul class=\"fig-list\"><li><code>CsmGeneral</code>: Allgemeine Modulkonfiguration (Multiplizität implizit 1..1, da keine Einschränkung angegeben).\n</li><li><code>CsmJobs</code>: Job-Definitionen und -Verwaltung (Multiplizität 0..1).\n</li><li><code>CsmKeys</code>: Schlüsselverwaltung und Key-Konfiguration (Multiplizität 0..1).\n</li><li><code>CsmPrimitives</code>: Kryptografische Primitiven und Algorithmen (Multiplizität 0..*).\n</li><li><code>CsmQueues</code>: Warteschlangen zur asynchronen Jobabwicklung (Multiplizität 0..1).\n</li><li><code>CsmCallbacks</code>: Callback-Konfiguration für Benachrichtigungen (Multiplizität 0..1).\n</li><li><code>CsmInOutRedirections</code>: Umleitungen von Ein- und Ausgabedaten (Multiplizität 0..1).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell- bzw. Konfigurationsstrukturdiagramm stellt die Abbildung keine Laufzeitaufrufe oder sequenziellen Nachrichtenflüsse dar. Sie bildet die statische Gliederung ab, anhand derer Konfigurationswerkzeuge (ECU Configuration Toolchain) die Parametersätze des CSM instanziieren und validieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Modell definiert verbindliche Vorgaben für die XML-basierte Konfigurationsbeschreibung (ARXML) des Crypto Service Managers. Generatoren und Konfigurationseditoren müssen die Multiplizitäten einhalten: <code>CsmPrimitives</code> erlaubt als einziger Untercontainer eine unbegrenzte Anzahl von Instanzen (0..*), während <code>CsmJobs</code>, <code>CsmKeys</code>, <code>CsmQueues</code>, <code>CsmCallbacks</code> und <code>CsmInOutRedirections</code> jeweils maximal einmal (0..1) konfiguriert werden dürfen. <code>CsmGeneral</code> ist für eine vollständige Modulkonfiguration obligatorisch.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3f8cbaf6db33b46b", "to": "FIG-dea8b06ee6403db6", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
